    const getStageChallenge = (stageId) => STAGE_CHALLENGES[stageId] || null;

    function isDrawableImg(img) {
      if (!img) return false;
      if (typeof HTMLCanvasElement !== 'undefined' && img instanceof HTMLCanvasElement) {
        return img.width > 0 && img.height > 0;
      }
      return Boolean(img.complete && img.naturalWidth > 0);
    }

    function loadSpriteImage(url, flagKey) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        if (img.naturalWidth > 0) ASSETS[flagKey] = true;
      };
      img.onerror = () => {
        ASSETS[flagKey] = false;
      };
      img.src = url;
      return img;
    }

