    // 離屏快取常用高頻貼圖提升效能
    const SPRITE_CACHE = (() => {
      function makeGem(size, inner, outer) {
        const c = document.createElement('canvas');
        c.width = size;
        c.height = size;
        const g = c.getContext('2d');
        const mid = size / 2;
        const r = size * 0.34;
        g.beginPath();
        g.moveTo(mid, mid - r);
        g.lineTo(mid + r * 0.85, mid);
        g.lineTo(mid, mid + r);
        g.lineTo(mid - r * 0.85, mid);
        g.closePath();
        g.fillStyle = inner;
        g.fill();
        g.lineWidth = 1.6;
        g.strokeStyle = outer;
        g.stroke();
        return c;
      }

      const coin = document.createElement('canvas');
      coin.width = 24;
      coin.height = 24;
      const cc = coin.getContext('2d');
      cc.beginPath();
      cc.arc(12, 12, 8, 0, Math.PI * 2);
      cc.fillStyle = '#fbbf24';
      cc.fill();
      cc.lineWidth = 1.8;
      cc.strokeStyle = '#fef3c7';
      cc.stroke();

      const poopEmoji = document.createElement('canvas');
      poopEmoji.width = 36;
      poopEmoji.height = 36;
      const pc = poopEmoji.getContext('2d');
      pc.font = '26px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif';
      pc.textAlign = 'center';
      pc.textBaseline = 'middle';
      pc.fillText('💩', 18, 19);

      const kuangStamp = document.createElement('canvas');
      kuangStamp.width = 28;
      kuangStamp.height = 28;
      const kc = kuangStamp.getContext('2d');
      kc.beginPath();
      kc.arc(14, 14, 12, 0, Math.PI * 2);
      kc.fillStyle = '#ffedd5';
      kc.fill();
      kc.lineWidth = 2;
      kc.strokeStyle = '#fb923c';
      kc.stroke();
      kc.font = '900 15px "Noto Sans TC", sans-serif';
      kc.textAlign = 'center';
      kc.textBaseline = 'middle';
      kc.fillStyle = '#c2410c';
      kc.fillText('曠', 14, 15);

      const animals = {};
      ANIMAL_EMOJIS.forEach(em => {
        const ac = document.createElement('canvas');
        ac.width = 48;
        ac.height = 48;
        const actx = ac.getContext('2d');
        actx.font = '34px "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", sans-serif';
        actx.textAlign = 'center';
        actx.textBaseline = 'middle';
        actx.fillText(em, 24, 26);
        animals[em] = ac;
      });

      const strawberryCake = document.createElement('canvas');
      strawberryCake.width = 96;
      strawberryCake.height = 96;
      const scCtx = strawberryCake.getContext('2d');
      // 粉嫩奶油草莓蛋糕（96x96 高解析圖樣，供孟寶 wave 詛咒／海嘯使用）
      scCtx.fillStyle = 'rgba(244, 114, 182, 0.25)';
      scCtx.beginPath();
      scCtx.ellipse(48, 82, 34, 8, 0, 0, Math.PI * 2);
      scCtx.fill();
      // 蛋糕體與雙層草莓夾心
      scCtx.fillStyle = '#ffe4e6';
      scCtx.strokeStyle = '#9f1239';
      scCtx.lineWidth = 3;
      scCtx.beginPath();
      scCtx.roundRect(16, 44, 64, 34, 9);
      scCtx.fill();
      scCtx.stroke();
      scCtx.fillStyle = '#fb7185';
      scCtx.fillRect(18, 59, 60, 7);
      scCtx.fillStyle = '#fecdd3';
      scCtx.fillRect(18, 66, 60, 5);
      // 頂層波浪鮮奶油淋面
      scCtx.fillStyle = '#fff9fb';
      scCtx.strokeStyle = '#f43f5e';
      scCtx.lineWidth = 2.4;
      scCtx.beginPath();
      scCtx.moveTo(13, 46);
      scCtx.quadraticCurveTo(28, 30, 48, 30);
      scCtx.quadraticCurveTo(68, 30, 83, 46);
      scCtx.lineTo(80, 55);
      scCtx.quadraticCurveTo(71, 47, 63, 56);
      scCtx.quadraticCurveTo(55, 47, 48, 56);
      scCtx.quadraticCurveTo(41, 47, 33, 56);
      scCtx.quadraticCurveTo(25, 47, 16, 55);
      scCtx.closePath();
      scCtx.fill();
      scCtx.stroke();
      // 頂部鮮紅大草莓＋籽點＋綠蒂頭
      scCtx.fillStyle = '#e11d48';
      scCtx.strokeStyle = '#881337';
      scCtx.lineWidth = 2.4;
      scCtx.beginPath();
      scCtx.moveTo(48, 10);
      scCtx.quadraticCurveTo(63, 18, 59, 34);
      scCtx.quadraticCurveTo(48, 40, 37, 34);
      scCtx.quadraticCurveTo(33, 18, 48, 10);
      scCtx.closePath();
      scCtx.fill();
      scCtx.stroke();
      scCtx.fillStyle = '#fecdd3';
      scCtx.beginPath();
      scCtx.ellipse(43, 21, 2.8, 5.2, -0.35, 0, Math.PI * 2);
      scCtx.fill();
      scCtx.fillStyle = '#fde047';
      for (const [sx, sy] of [[52, 20], [49, 28], [42, 30], [54, 29]]) {
        scCtx.beginPath();
        scCtx.arc(sx, sy, 1.3, 0, Math.PI * 2);
        scCtx.fill();
      }
      scCtx.fillStyle = '#22c55e';
      scCtx.strokeStyle = '#14532d';
      scCtx.lineWidth = 1.8;
      scCtx.beginPath();
      scCtx.ellipse(48, 12, 12, 4.6, 0, 0, Math.PI * 2);
      scCtx.fill();
      scCtx.stroke();

      return {
        expSmall: makeGem(24, '#38bdf8', '#e0f2fe'),
        expLarge: makeGem(32, '#a855f7', '#f3e8ff'),
        coin,
        poopEmoji,
        kuangStamp,
        strawberryCake,
        animals
      };
    })();

    // 空間雜湊網格（加速大量敵人碰撞與範圍搜尋）
    const SpatialGrid = (() => {
      const cellSize = 110;
      const buckets = new Map();
      return {
        clear() {
          buckets.clear();
        },
        insert(obj) {
          const cx = Math.floor(obj.x / cellSize);
          const cy = Math.floor(obj.y / cellSize);
          const key = `${cx},${cy}`;
          let arr = buckets.get(key);
          if (!arr) {
            arr = [];
            buckets.set(key, arr);
          }
          arr.push(obj);
        },
        query(x, y, radius, cb) {
          const minX = Math.floor((x - radius) / cellSize);
          const maxX = Math.floor((x + radius) / cellSize);
          const minY = Math.floor((y - radius) / cellSize);
          const maxY = Math.floor((y + radius) / cellSize);
          for (let cx = minX; cx <= maxX; cx++) {
            for (let cy = minY; cy <= maxY; cy++) {
              const arr = buckets.get(`${cx},${cy}`);
              if (!arr) continue;
              for (let i = 0; i < arr.length; i++) {
                cb(arr[i]);
              }
            }
          }
        }
      };
    })();

