    function getGearFusionExtraLines(gear, star) {
      if (!gear || star <= 0) return [];
      const lines = [`基礎屬性 +${star * 25}%`];
      if (gear.slot === 'head') lines.push(`額外攻擊 +${star * 8}%`, `暴擊率 +${star * 3}%`);
      else if (gear.slot === 'face') lines.push(`額外攻擊 +${star * 7}%`, `技能冷卻 -${star * 3}%`);
      else if (gear.slot === 'back') lines.push(`額外生命 +${star * 60}`, `額外移速 +${star * 4}%`);
      if (gear.rarity === 'SSR') lines.push(`SSR 共鳴：全屬性 +${star * 5}%`);
      return lines;
    }
