        return {
          ...item,
          kind: 'gear',
          detail: item.desc + '　' + item.statLabel + (eff ? `｜★1合成【${eff.title}】：${eff.summary(1)}` : ''),
          obtain: (item.rarity === 'SSR' ? 'SSR 傳說配飾' : (item.rarity === 'SR' ? 'SR 荒唐配飾' : 'R 基礎配飾')) + '：由星願召喚池取得，重複可低價合成突破解鎖專屬被動/技能。'
        };
