    function isDexEntryUnlocked(entry) {
      if (entry.kind === 'hero') return isHeroUnlocked(entry.id);
      if (entry.kind === 'gear') return (saveData.ownedGears[entry.id] || 0) > 0;
      if (entry.kind === 'boss') return saveData.seenEnemies.includes(entry.id) || saveData.clearedStages.includes(entry.stageId);
      return saveData.seenEnemies.includes(entry.id);
    }
    function dexCategoryCounts() {
      const catalog = getDexCatalog();
      return Object.fromEntries(Object.entries(catalog).map(([key, entries]) => [key, { found:entries.filter(isDexEntryUnlocked).length, total:entries.length }]));
    }
    function updateDexProgressIndicator() {
      const counts = dexCategoryCounts();
      const found = Object.values(counts).reduce((sum, value) => sum + value.found, 0);
      const total = Object.values(counts).reduce((sum, value) => sum + value.total, 0);
      const badge = document.getElementById('ui-dex-progress');
      if (badge) badge.textContent = found + ' / ' + total;
      const overall = document.getElementById('dex-overall-progress');
      if (overall) overall.textContent = found + ' / ' + total + ' 已收錄';
      ['characters','enemies','gear'].forEach(key => {
        const countEl = document.getElementById('dex-count-' + key);
        if (countEl) countEl.textContent = counts[key].found + ' / ' + counts[key].total;
      });
    }
    function addDexDiscovery(id) {
      if (!id || saveData.seenEnemies.includes(id)) return;
      saveData.seenEnemies.push(id);
      persistGameProgress();
      updateDexProgressIndicator();
    }
    function ensureLegacyDexDiscoveries() {
      if (!Array.isArray(saveData.seenEnemies)) saveData.seenEnemies = [];
      const add = id => { if (!saveData.seenEnemies.includes(id)) saveData.seenEnemies.push(id); };
      saveData.clearedStages.forEach(stageId => {
        const index = STAGES.findIndex(stage => stage.id === stageId);
        if (index < 0) return;
        add('boss-' + stageId);
        if (index < 5) {
          [['enemy-normal','enemy-elite'],['enemy-mage'],['enemy-marryFriend'],['enemy-mermaidStrong'],['enemy-transformer']][index].forEach(add);
        } else if (index < 10) {
          CHAPTER_TWO_ENCOUNTERS[index - 5].forEach(kind => add('enemy-' + kind));
          add('enemy-babaBoyi');
        } else if (index < 15) {
          CHAPTER_THREE_ENCOUNTERS[Math.min(4, index - 10)].forEach(kind => add('enemy-' + kind));
          add('enemy-babaBoyi');
        } else if (index < 20) {
          CHAPTER_FOUR_ENCOUNTERS[Math.min(4, index - 15)].forEach(kind => add('enemy-' + kind));
          add('enemy-cottonCandyGolem');
        } else if (index < 25) {
          CHAPTER_FIVE_ENCOUNTERS[Math.min(4, index - 20)].forEach(kind => add('enemy-' + kind));
          add('enemy-abyssServerTitan');
        } else {
          CHAPTER_SIX_ENCOUNTERS[Math.min(4, index - 25)].forEach(kind => add('enemy-' + kind));
          add('enemy-archonWarden');
        }
      });
    }
