        gearTrailCd: 0,
        gearWingBladeCd: 0,
        gearTrackCd: 0,
        gearKillCount: 0,
        gearGemCount: 0,
        gearZapCd: 0,
        gearExpHealCd: 0,
        gearHurtVfxCd: 0,
        skillSealImmunityTimer: 0,
        unsealBuffTimer: 0,
