        pickupRange: basePickup,
        level: 1,
        exp: 0,
        nextExp: 10,
        facing: 1,
        walkCycle: 0,
        invuln: 0,
        sleepAnimTimer: 0,
        atkSpdBoostTimer: 0,
        atkSpdBoostMult: 1,
