            clearEnemyOrbsInCircle(p.x, p.y, ringR * 0.9);
            gameState.danDingVfx.push({
              type: 'flameStorm',
              x: p.x,
              y: p.y,
              radius: ringR,
              life: 1.25,
              maxLife: 1.25
            });
            gameState.danDingVfx.push({
              type: 'storyZone',
              x: target ? target.x : p.x,
              y: target ? target.y : p.y,
              radius: 215,
              tickTimer: 0.25,
              tickDmg: 64 * p.dmgMult,
              isEvo: true,
              life: 3.6,
              maxLife: 3.6
            });
