      const reach = t < .16 ? -.12 * Math.sin((t / .16) * Math.PI) : (t < .58 ? 1.08 * (1 - Math.pow(1 - (t - .16) / .42, 3)) : .94 + .06 * Math.cos(((t - .58) / .42) * Math.PI));
