      const scale = (0.82 + 0.48 * Math.min(1, t * 3) + Math.sin(t * Math.PI) * .08) * (fx.isEvo ? 1.3 : 1.12);
      const swing = (1 - Math.min(1, t * 1.8)) * -.22 + (t > .58 ? Math.sin((t - .58) / .42 * Math.PI) * .06 : 0);
