          const puddleBubbles = REDUCED_BEAR_VFX ? 4 : 8;
          for (let i = 0; i < puddleBubbles; i++) {
            const a = i * Math.PI * 2 / puddleBubbles + fx.phase * .12, r = fx.radius * (.62 + Math.sin(fx.phase + i) * .035);
            ctx.fillStyle = `${fx.color}58`; ctx.beginPath(); ctx.arc(Math.cos(a) * r, Math.sin(a) * r, fx.radius * .095, 0, Math.PI * 2); ctx.fill();
          }
          ctx.restore();
