          const lava = ctx.createRadialGradient(0, 0, radius * .08, 0, 0, radius);
          lava.addColorStop(0, 'rgba(255,244,190,.92)'); lava.addColorStop(.28, 'rgba(255,105,180,.88)');
          lava.addColorStop(.68, 'rgba(236,36,125,.62)'); lava.addColorStop(1, 'rgba(190,24,93,0)');
          ctx.fillStyle = lava;
          ctx.beginPath();
          const points = REDUCED_BEAR_VFX ? 14 : (fx.isEvo ? 28 : 20);
