            ctx.fillStyle = '#facc15';
            ctx.strokeStyle = '#d97706';
            ctx.lineWidth = 1.6;
            ctx.beginPath();
            ctx.ellipse(0, 1, 13, 8, 0, 0, Math.PI * 2);
