          ctx.strokeRect(-54, -24, 108, 50);
          ctx.fillStyle = '#ec4899';
          ctx.fillRect(-54, -24, 108, 12);
          ctx.font = '900 11px "Noto Sans TC", sans-serif';
          ctx.textAlign = 'center';
          ctx.fillStyle = '#fde047';
          ctx.fillText(proj.label || '全網刷屏地獄', 0, -2);
