      const skipBtn = document.getElementById('btn-skip-ritual');

      const hasUR = results.some(r => r.rarity === 'UR');
      const hasSSR = results.some(r => r.rarity === 'UR' || r.rarity === 'SSR');
      const hasSR = results.some(r => r.rarity === 'SR');
      const themeColor = hasUR ? '#f472b6' : (hasSSR ? '#fde047' : (hasSR ? '#c084fc' : '#38bdf8'));
      const themeGlow = hasUR ? 'rgba(244, 114, 182, 0.92)' : (hasSSR ? 'rgba(253, 224, 71, 0.9)' : (hasSR ? 'rgba(192, 132, 252, 0.82)' : 'rgba(56, 189, 248, 0.75)'));
      const rarityRank = { R: 0, SR: 1, SSR: 2, UR: 3 };
      const revealResults = [...results].sort((a, b) => (rarityRank[a.rarity] ?? 1) - (rarityRank[b.rarity] ?? 1));
      const boardHeader = document.querySelector('.board-header');
      const boardWriting = document.querySelector('.board-writing');
      boardHeader.textContent = '218 教室・今日點名';
      boardWriting.textContent = '準備好迎接命運了嗎？';

      gCanvas.width = window.innerWidth;
      gCanvas.height = window.innerHeight;
      overlay.classList.remove('cinematic-standalone', 'ritual-active', 'ritual-reveal', 'ritual-ur', 'ritual-ssr', 'ritual-sr', 'ritual-bear', 'ritual-hero-pudding', 'ritual-hero-bigSteelGate', 'ritual-hero-aooni', 'ritual-hero-naKeYa', 'ritual-hero-bigPartner', 'ritual-hero-bear', 'ritual-hero-gloryGod', 'ritual-hero-mudCat', 'ritual-hero-moonYue', 'ritual-hero-danDing', 'ritual-hero-sakuraClock', 'ritual-hero-purpleCow', 'ritual-hero-bigYan', 'ritual-reveal-pudding', 'ritual-reveal-bigSteelGate', 'ritual-reveal-aooni', 'ritual-reveal-naKeYa', 'ritual-reveal-bigPartner', 'ritual-reveal-bear', 'ritual-reveal-gloryGod', 'ritual-reveal-mudCat', 'ritual-reveal-moonYue', 'ritual-reveal-danDing', 'ritual-reveal-sakuraClock', 'ritual-reveal-purpleCow', 'ritual-reveal-bigYan');
      void overlay.offsetWidth;
      overlay.classList.add('ritual-active');
      if (hasUR) overlay.classList.add('ritual-ur');
      if (hasSSR) overlay.classList.add('ritual-ssr');
      if (hasSR) overlay.classList.add('ritual-sr');
      overlay.classList.remove('hidden');
      ritualBanner.classList.remove('hidden');
      singleRevealEl.classList.add('hidden');
      summaryViewEl.classList.add('hidden');
      skipBtn.classList.remove('hidden');

      titleEl.textContent = hasUR
