      let shareToastTimer = null;
      function showShareToast(message, isError = false) {
        const toast = document.getElementById('share-toast');
        if (!toast) return;
        toast.textContent = message;
        toast.className = isError
          ? 'fixed bottom-5 left-1/2 -translate-x-1/2 z-50 pointer-events-none rounded-full border border-rose-300/60 bg-slate-950/95 px-4 py-2 text-xs font-black text-rose-200 shadow-2xl backdrop-blur-md'
          : 'fixed bottom-5 left-1/2 -translate-x-1/2 z-50 pointer-events-none rounded-full border border-emerald-300/60 bg-slate-950/95 px-4 py-2 text-xs font-black text-emerald-200 shadow-2xl backdrop-blur-md';
        toast.classList.remove('hidden');
        if (shareToastTimer) clearTimeout(shareToastTimer);
        shareToastTimer = setTimeout(() => {
          toast.classList.add('hidden');
        }, 2800);
      }

      async function copyTextToClipboard(text) {
        if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
          try {
            await navigator.clipboard.writeText(text);
            return true;
          } catch {
            // 某些內嵌視窗會拒絕 Clipboard API，改用隱藏文字框複製
          }
        }
        try {
          const ta = document.createElement('textarea');
          ta.value = text;
          ta.setAttribute('readonly', '');
          ta.style.position = 'fixed';
          ta.style.top = '-9999px';
          ta.style.left = '-9999px';
          document.body.appendChild(ta);
          ta.focus();
          ta.select();
          const ok = document.execCommand('copy');
          document.body.removeChild(ta);
          return ok;
        } catch {
          return false;
        }
      }

      function flashShareButtonLabel(btn, tempText) {
        if (!btn) return;
        if (!btn.dataset.origHtml) btn.dataset.origHtml = btn.innerHTML;
        if (btn._shareResetTimer) clearTimeout(btn._shareResetTimer);
        btn.textContent = tempText;
        btn._shareResetTimer = setTimeout(() => {
          btn.innerHTML = btn.dataset.origHtml;
          btn._shareResetTimer = null;
        }, 2400);
      }

      async function shareGameLink(triggerBtn) {
        SoundFX.click();
        const shareText = '🎮 快來玩《218 family survivor》！218 家族超熱血 Roguelite 倖存者割草遊戲，一起衝榜！';
        const statusEl = document.getElementById('settings-share-state');

        if (typeof navigator.share === 'function') {
          try {
            await navigator.share({
              title: '218 family survivor',
              text: shareText,
              url: GAME_SHARE_URL
            });
            flashShareButtonLabel(triggerBtn, '✓ 已分享！');
            if (statusEl) {
              statusEl.className = 'mt-2 min-h-4 text-xs font-bold text-emerald-300';
              statusEl.textContent = '感謝分享！快約好友一起開局';
            }
            showShareToast('✅ 感謝分享！快約好友一起開局');
            return;
          } catch (err) {
            if (err && err.name === 'AbortError') return;
          }
        }

        const copied = await copyTextToClipboard(`${shareText} ${GAME_SHARE_URL}`);
        if (copied) {
          flashShareButtonLabel(triggerBtn, '✓ 已複製連結！');
          if (statusEl) {
            statusEl.className = 'mt-2 min-h-4 text-xs font-bold text-emerald-300';
            statusEl.textContent = '已複製遊戲連結與分享文案！';
          }
          showShareToast('✅ 已複製分享內容與遊戲連結，可直接貼上分享！');
        } else {
          if (statusEl) {
            statusEl.className = 'mt-2 min-h-4 text-xs font-bold text-rose-300';
            statusEl.textContent = `請手動複製：${GAME_SHARE_URL}`;
          }
          showShareToast(`🔗 請手動複製連結：${GAME_SHARE_URL}`, true);
        }
      }

