      document.getElementById('btn-dev-maxall').addEventListener('click', () => {
        if (!saveData.developerMode) return;
        if (gameState.mode !== 'PLAYING' || !gameState.player) return;
        const p = gameState.player;
        SoundFX.levelup();

        if (Array.isArray(p.unlockableSkills)) {
          p.unlockableSkills.forEach(skId => {
            if (!p.skills.some(s => s.id === skId) && p.skills.length < 4) {
              p.skills.push({ id: skId, level: 1, awakened: false, timer: 0.1, shotCounter: 0 });
            }
          });
        }
        p.skills.forEach(sk => {
          sk.level = 5;
          sk.awakened = true;
        });

        const heroPassives = Array.isArray(p.availablePassives) ? p.availablePassives : [];
        heroPassives.forEach(pid => {
          const def = SKILL_CATALOG[pid];
          if (!def) return;
          if (!p.passives.includes(pid)) p.passives.push(pid);
          const curLv = getPassiveLevel(p, pid);
          const diff = PASSIVE_MAX_LV - curLv;
          if (diff > 0) {
            p.passiveLevels[pid] = PASSIVE_MAX_LV;
            if (def.statType === 'atk') p.dmgMult += 0.08 * diff;
            if (def.statType === 'spd') p.speed *= Math.pow(1.06, diff);
            if (def.statType === 'magnet') p.pickupRange *= Math.pow(1.15, diff);
            if (def.statType === 'heal') p.maxHp += 12 * diff;
          }
        });

        p.hp = p.maxHp;
        p.level = Math.max(p.level, 35);
        p.nextExp = calcNextLevelExp(p.level, gameState.stageIndex);
        updateBattleHUD();
        addFloatText(p.x, p.y - 45, '⚡ 全招式 LV.MAX 覺醒滿級！', '#67e8f9', 18);
      });

